function searchPage(keys, target) {
  let l = 0, r = keys.length - 1;
  while (l <= r) {
    const mid = (l + r) >> 1;
    if (keys[mid] === target) return mid;
    if (keys[mid] < target) l = mid + 1;
    else r = mid - 1;
  }
  return -1;
}

